def variant(I, vert_fills, horiz_fills):
    H,W=len(I),len(I[0])
    srr=[r for r in range(H) if all(x==8 for x in I[r])]
    scc=[c for c in range(W) if all(I[r][c]==8 for r in range(H))]
    rb=[(a,b) for a,b in zip([-1]+srr,srr+[H])]
    cb=[(a,b) for a,b in zip([-1]+scc,scc+[W])]
    marks=defaultdict(list)
    for r in range(H):
        for c in range(W):
            if I[r][c] not in (0,8):
                bi=next(i for i,(x,y) in enumerate(rb) if b[0]<=r<=b[1])
                bj=next(j for j,(x,y) in enumerate(cb) if b[0]<=c<=b[1])
                marks[I[r][c]].append((bi,bj,r,c))
    res=[[0]*W for _ in range(H)]
    for v,ps in marks.items():
        rs={p[2] for p in ps}; cs={p[3] for p in ps}
        if len(rs)>1:
            rmin=min(p[2] for p in ps); rmax=max(p[2] for p in ps)
            verts=vert_fills(v,rs,cs,ps,rmin,rmax)
            for (r,cj) in verts:
                for r0 in range(rb[cj][0],rb[cj][1]+1):
                    for r1 in range(rmin,rmax+1):
                        res[r1][r0]=v
        else:
            cmin=min(p[3] for p in ps); cmax=max(p[3] for p in ps)
            horis=horiz_fills(v,rs,cs,ps,cmin,cmax)
            for (bi,cj) in horis:
                for r in range(rb[bi][0],rb[bi][1]+1):
                    for c in range(cb[cj][0],cb[cj][1]+1):
                        res[r][c]=v
    out=[[6 if res[r][c]!=0 and any(...) else res[r][c] for c in range(W)] for r in range(H)]
    # overlaps: count layers
    cnt=[[0]*(W) for _ in range(H)]
    for v,ps in marks.items():
        rs={p[2] for p in ps}; cs={p[3] for p in ps}
        if len(rs)>1:
